// Translation follows only the generated reading path. Original source
// components and the saved snapshot are never rewritten.
export function canTranslateViewToEnglish(sourceLanguage) {
  const language = String(sourceLanguage || '').trim().toLowerCase();
  if (!/^[a-z]{2,3}(?:-[a-z]+)?$/.test(language)) return false;
  return !['en', 'und', 'mul', 'zxx'].includes(language.split('-')[0]);
}

export function cleanViewBridge(value) {
  return String(value || '')
    .replace(/\s*\[[a-z0-9_-]+:[^\]]+\]/gi, '')
    .replace(/\s*\[(?:\d+(?:\s*,\s*\d+)*)\]/g, '')
    .replace(/\s+([.,!?])/g, '$1')
    .trim();
}

export function viewTranslationEntries(view) {
  const entries = [];
  const add = (id, text) => { if (typeof text === 'string' && text.trim()) entries.push({ id, text: text.trim() }); };
  add('title', view?.title);
  add('question', view?.question);
  add('summary', view?.dek);
  for (const [s, section] of (view?.sections || []).entries()) {
    add(`section.${s}`, section.heading);
    for (const [b, block] of (section.blocks || []).entries()) {
      if (block.kind === 'bridge') add(`bridge.${s}.${b}`, cleanViewBridge(block.text));
    }
  }
  return entries;
}

export async function translationFingerprint(entries) {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(JSON.stringify(entries)));
  return [...new Uint8Array(digest)].map(n => n.toString(16).padStart(2, '0')).join('');
}

export function translationBatches(entries, limit = 5000) {
  const batches = [];
  let batch = [], size = 0;
  for (const entry of entries) {
    const length = [...entry.text].length;
    if (length > limit) throw new Error('Translation passage too long');
    if (size + length > limit && batch.length) { batches.push(batch); batch = []; size = 0; }
    batch.push(entry); size += length;
  }
  if (batch.length) batches.push(batch);
  return batches;
}
